export const SUPPORTED_CURRENCIES = Object.freeze(['USD', 'EUR', 'GBP']);

export const INVOICE_STATUS = Object.freeze({
  DRAFT: 'DRAFT',
  FINALIZED: 'FINALIZED',
  VOIDED: 'VOIDED'
});

export const ROUNDING_MODES = Object.freeze({
  HALF_AWAY_FROM_ZERO: 'HALF_AWAY_FROM_ZERO',
  FLOOR: 'FLOOR'
});

export const MAX_BPS = 10_000;
export const WIRE_SCHEMA_VERSION = 'LP-WIRE-V1';
export const DEFAULT_TIME_ZONE = 'UTC';
import { WIRE_SCHEMA_VERSION } from './constants.mjs';

/**
 * Legacy LP-WIRE-V1 deterministic 32-bit FNV-1a digest serializer.
 * FROZEN CONTRACT: downstream settlement consumers rely on exact byte output.
 *
 * @param {object} summary
 * @returns {string}
 */
export function encodeFrozenWireDigest(summary = {}) {
  const invoiceId = String(summary.invoiceId || '');
  const accountId = String(summary.accountId || '');
  const currency = String(summary.currency || 'USD');
  const totalDueCents = Math.trunc(Number(summary.totalDueCents || 0));
  const status = String(summary.status || 'FINALIZED');
  const canonical = `${WIRE_SCHEMA_VERSION}|${invoiceId}|${accountId}|${currency}|${totalDueCents}|${status}`;

  let hash = 0x811c9dc5;
  for (let i = 0; i < canonical.length; i += 1) {
    hash ^= canonical.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  const hex = (hash >>> 0).toString(16).padStart(8, '0');
  return `${WIRE_SCHEMA_VERSION}:${hex}:${totalDueCents}`;
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Computes graduated (marginal/tiered) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
 */
export function computeGraduatedCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    return { totalCents: 0, breakdown: [] };
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    if (units <= prevUpTo && i > 0) break;

    const bounded = Math.min(units, cap);
    const bandUnits = Math.max(0, bounded - prevUpTo + (prevUpTo > 0 ? 1 : 0));
    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    totalCents += subtotalCents;
    breakdown.push({
      tierIndex: i,
      upTo: cap === Infinity ? null : cap,
      units: bandUnits,
      unitRateCents: tier.unitRateCents,
      subtotalCents
    });
    if (cap === Infinity) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}

/**
 * Computes volume (all-units-at-matched-tier-rate) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, matchedTierIndex: number, unitRateCents: number }}
 */
export function computeVolumeCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
  }
  if (units === 0) {
    return { totalCents: 0, matchedTierIndex: 0, unitRateCents: tiers[0].unitRateCents };
  }

  for (let i = 0; i < tiers.length; i += 1) {
    const cap = tiers[i].upTo === null || tiers[i].upTo === undefined ? Infinity : tiers[i].upTo;
    if (units <= cap) {
      return {
        totalCents: Math.round(units * tiers[i].unitRateCents),
        matchedTierIndex: i,
        unitRateCents: tiers[i].unitRateCents
      };
    }
  }
  const lastIdx = tiers.length - 1;
  return {
    totalCents: Math.round(units * tiers[lastIdx].unitRateCents),
    matchedTierIndex: lastIdx,
    unitRateCents: tiers[lastIdx].unitRateCents
  };
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { computeGraduatedCharge, computeVolumeCharge } from '../src/tierEngine.mjs';
import { applyCredits, summarizePoolBalance } from '../src/creditPool.mjs';

test('graduated charge within first tier', () => {
  const tiers = [
    { upTo: 100, unitRateCents: 10 },
    { upTo: null, unitRateCents: 5 }
  ];
  const res = computeGraduatedCharge(50, tiers);
  assert.equal(res.totalCents, 500);
  assert.equal(res.breakdown.length, 1);
  assert.equal(res.breakdown[0].units, 50);
});

test('volume charge selects matching tier', () => {
  const tiers = [
    { upTo: 100, unitRateCents: 10 },
    { upTo: null, unitRateCents: 6 }
  ];
  const res = computeVolumeCharge(150, tiers);
  assert.equal(res.totalCents, 900);
  assert.equal(res.matchedTierIndex, 1);
});

test('applyCredits reduces charge from active grant', () => {
  const grants = [
    { grantId: 'g1', remainingCents: 800, effectiveFromMs: 0, expiresAtMs: 50_000 }
  ];
  const res = applyCredits(500, grants, 10_000);
  assert.equal(res.appliedCents, 500);
  assert.equal(res.remainingChargeCents, 0);
  assert.deepEqual(res.allocations, [{ grantId: 'g1', appliedCents: 500 }]);
});

test('summarizePoolBalance sums positive grants', () => {
  const grants = [
    { grantId: 'g1', remainingCents: 400, effectiveFromMs: 0, expiresAtMs: 50_000 },
    { grantId: 'g2', remainingCents: 0, effectiveFromMs: 0, expiresAtMs: 50_000 }
  ];
  const summary = summarizePoolBalance(grants, 10_000);
  assert.equal(summary.availableCents, 400);
  assert.equal(summary.activeCount, 1);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { buildInvoice } from '../src/invoiceBuilder.mjs';
import { encodeFrozenWireDigest } from '../src/frozenWire.mjs';

test('buildInvoice computes subtotal, credits, totalDue, and frozen wire digest', () => {
  const tiers = [
    { upTo: 100, unitRateCents: 10 },
    { upTo: null, unitRateCents: 5 }
  ];
  const inv = buildInvoice({
    invoiceId: 'inv-100',
    accountId: 'acct-alpha',
    currency: 'USD',
    usageRows: [{ metric: 'api_calls', units: 60, tiers }],
    grants: [{ grantId: 'g1', remainingCents: 200, effectiveFromMs: 0, expiresAtMs: 99_999 }],
    asOfMs: 5000
  });
  assert.equal(inv.usageSubtotalCents, 600);
  assert.equal(inv.appliedCreditsCents, 200);
  assert.equal(inv.totalDueCents, 400);
  assert.equal(
    inv.wireDigest,
    encodeFrozenWireDigest({
      invoiceId: 'inv-100',
      accountId: 'acct-alpha',
      currency: 'USD',
      totalDueCents: 400,
      status: 'FINALIZED'
    })
  );
});
# LedgerPulse

Zero-dependency Node.js ESM metering, credit allocation, windowing, and invoice settlement engine.

## Conventions
- All monetary amounts are represented as **integer cents** (`number` safe integers).
- All timestamps are **UTC epoch milliseconds** (`number` finite integers).
- Inputs (`tiers`, `grants`, `events`, `lineItems`) must never be mutated by engine functions.
- `src/frozenWire.mjs` implements the legacy `LP-WIRE-V1` digest wire contract and must stay compatible.

## Modules (`src/`)
- `constants.mjs`: Frozen currencies, invoice statuses, and protocol constants.
- `errors.mjs`: `LedgerError` and canonical error codes.
- `frozenWire.mjs`: Legacy wire digest encoder (`encodeFrozenWireDigest`).
- `clock.mjs`: IANA timezone billing window boundary & enumeration helpers.
- `tierEngine.mjs`: Graduated and volume pricing calculators.
- `creditPool.mjs`: Promotional / prepaid credit grant allocation & pool summaries.
- `idempotencyGuard.mjs`: Bounded-capacity TTL idempotency store.
- `queryDsl.mjs`: Safe, eval-free boolean event filter tokenizer, parser, and compiler.
- `batchIngestor.mjs`: Buffered async event ingestor with sequence watermarks.
- `invoiceBuilder.mjs`: End-to-end usage metering, credit application, and invoice builder.
