import { INVOICE_STATUS } from './constants.mjs';
import { ERROR_CODES, LedgerError } from './errors.mjs';
import { computeGraduatedCharge } from './tierEngine.mjs';
import { applyCredits, summarizePoolBalance } from './creditPool.mjs';
import { encodeFrozenWireDigest } from './frozenWire.mjs';

function computeInvoice({
  invoiceId,
  accountId,
  currency = 'USD',
  usageRows = [],
  grants = [],
  asOfMs = 0
} = {}) {
  const lineItems = [];
  let usageSubtotalCents = 0;

  for (const row of usageRows) {
    const { totalCents } = computeGraduatedCharge(row.units, row.tiers);
    usageSubtotalCents += totalCents;
    lineItems.push({
      metric: row.metric,
      units: row.units,
      amountCents: totalCents
    });
  }

  const creditResult = applyCredits(usageSubtotalCents, grants, asOfMs);
  const totalDueCents = creditResult.remainingChargeCents;
  const status = INVOICE_STATUS.FINALIZED;
  const wireDigest = encodeFrozenWireDigest({
    invoiceId,
    accountId,
    currency,
    totalDueCents,
    status
  });

  return {
    invoice: {
      invoiceId,
      accountId,
      currency,
      status,
      lineItems,
      usageSubtotalCents,
      appliedCreditsCents: creditResult.appliedCents,
      creditAllocations: creditResult.allocations,
      totalDueCents,
      wireDigest
    },
    updatedGrants: creditResult.updatedGrants
  };
}

/**
 * Builds an invoice from usage rows and credit grants.
 * Caller-supplied grants are not mutated.
 *
 * @param {object} params
 * @returns {object}
 */
export function buildInvoice(params = {}) {
  return computeInvoice(params).invoice;
}

/**
 * Creates a stateful settlement registry. Initial grants are cloned.
 * @param {Array<object>} initialGrants
 */
export function createSettlementRegistry(initialGrants = []) {
  if (!Array.isArray(initialGrants)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'initialGrants must be an array');
  }
  return {
    grants: initialGrants.map((g) => ({ ...g })),
    invoices: new Map(),
    // Cents restored onto already-expired grants; never spendable again.
    lockedExpiredCents: new Map()
  };
}

function usableGrants(registry) {
  return registry.grants.map((g) => ({
    ...g,
    remainingCents: g.remainingCents - (registry.lockedExpiredCents.get(g.grantId) || 0)
  }));
}

/**
 * Settles an invoice against the registry's grants, debiting registry state.
 */
export function settleInvoice(registry, invoiceParams = {}) {
  if (registry.invoices.has(invoiceParams.invoiceId)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'invoice already settled', {
      invoiceId: invoiceParams.invoiceId
    });
  }
  const { invoice } = computeInvoice({ ...invoiceParams, grants: usableGrants(registry) });
  for (const alloc of invoice.creditAllocations) {
    const grant = registry.grants.find((g) => g.grantId === alloc.grantId);
    grant.remainingCents -= alloc.appliedCents;
  }
  registry.invoices.set(invoice.invoiceId, structuredClone(invoice));
  return structuredClone(invoice);
}

/**
 * Voids a settled invoice and restores its credit allocations.
 */
export function voidInvoiceSettlement(registry, invoiceId, voidedAtMs) {
  const invoice = registry.invoices.get(invoiceId);
  if (!invoice) {
    throw new LedgerError(ERROR_CODES.ERR_UNKNOWN_INVOICE, 'unknown invoice', { invoiceId });
  }
  if (invoice.status === INVOICE_STATUS.VOIDED) {
    throw new LedgerError(ERROR_CODES.ERR_ALREADY_VOIDED, 'invoice already voided', { invoiceId });
  }

  let restoredActiveCents = 0;
  let restoredExpiredCents = 0;
  for (const alloc of invoice.creditAllocations) {
    const grant = registry.grants.find((g) => g.grantId === alloc.grantId);
    if (!grant) continue;
    grant.remainingCents += alloc.appliedCents;
    if (voidedAtMs < grant.expiresAtMs) {
      restoredActiveCents += alloc.appliedCents;
    } else {
      restoredExpiredCents += alloc.appliedCents;
      registry.lockedExpiredCents.set(
        grant.grantId,
        (registry.lockedExpiredCents.get(grant.grantId) || 0) + alloc.appliedCents
      );
    }
  }

  invoice.status = INVOICE_STATUS.VOIDED;
  invoice.voidedAtMs = voidedAtMs;

  return {
    invoiceId,
    status: INVOICE_STATUS.VOIDED,
    voidedAtMs,
    netDeltaCents: invoice.totalDueCents === 0 ? 0 : -invoice.totalDueCents,
    restoredActiveCents,
    restoredExpiredCents,
    reversalWireDigest: encodeFrozenWireDigest({ ...invoice, status: INVOICE_STATUS.VOIDED })
  };
}

/**
 * Returns cloned registry state: invoices, grants, and pool balance at asOfMs.
 */
export function getRegistrySnapshot(registry, asOfMs = 0) {
  return {
    invoices: [...registry.invoices.values()].map((i) => structuredClone(i)),
    grants: registry.grants.map((g) => ({ ...g })),
    poolBalance: summarizePoolBalance(usableGrants(registry), asOfMs)
  };
}
